// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: attacker address and an amount to send
    // General rule being tested:
    //   The reference contract only accepts fallback invocations that send exactly 10 ether.
    //   Therefore, for any fuzzed amount != 10 ether, calling fallback should NOT change pastBlockTime
    //   (it will revert) and thus pastBlockTime getter remains at its previous value (initially 0).
    // The mutant requires 1 ether, so there exist amounts (e.g., 1 ether) where mutant accepts but reference rejects.
    function testFuzz_property(address sender, uint256 value) public {
        // keep sender non-zero and value within reasonable bounds for sending
        vm.assume(sender != address(0));
        // limit value to below 100 ether to keep test reasonable but wide
        value = bound(value, 0, 100 ether);

        // record initial pastBlockTime and contract balance
        uint256 initialPast = c.pastBlockTime();
        uint256 initialBal = address(c).balance;

        // Set up sender with the fuzzed balance
        vm.deal(sender, value);
        // Try calling fallback with the fuzzed value as sender
        bool ok;
        vm.prank(sender);
        try c.f{value: value}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert (single assertTrue):
        // For the reference contract, any call that does NOT supply exactly 10 ether must revert,
        // therefore pastBlockTime remains unchanged (still initialPast). We assert that either
        // the call reverted (ok == false) OR, if it succeeded, it must have been with exactly 10 ether
        // and thus pastBlockTime has changed to a nonzero value >= block.timestamp. This assertion
        // is satisfied by the reference for all inputs, but the mutant (which accepts 1 ether) will
        // allow success for value == 1 ether where the reference would have reverted, violating the rule.

        // Read current pastBlockTime
        uint256 afterPast = c.pastBlockTime();

        // Single assertion capturing the universal rule:
        // Either the call reverted (ok == false) or the call succeeded AND value == 10 ether and pastBlockTime changed.
        assertTrue(
            (!ok && afterPast == initialPast)
            || (ok && value == 10 ether && afterPast >= initialPast)
        );
    }
}

