pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the caller and the sent value (the deciding parameter)
    function testFuzz_property(address caller, uint256 value, uint256 time, uint256 blk) public {
        // keep value in a reasonable range and caller non-zero
        vm.assume(caller != address(0));
        // bound value to a wide range including 1 ether and 10 ether
        value = bound(value, 0, 20 ether);

        // set up environment: balance for caller so they can send value
        vm.deal(caller, value + 1 ether);

        // set block timestamp and number to controlled values
        // ensure time increases across calls in general; we just set it to fuzzed time
        vm.warp(time);
        vm.roll(blk);

        // read prior pastBlockTime and prior contract balance
        uint256 priorTime = c.pastBlockTime();
        uint256 priorBal = address(c).balance;

        // perform the low-level payable call by using prank to make caller the msg.sender
        bool ok;
        vm.prank(caller);
        try c.f{value: value}() {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, the reference contract has the invariant:
        // If the sent value is not exactly 10 ether then the call must revert and thus
        // pastBlockTime remains unchanged (and balance unchanged). We assert that
        // for any fuzzed inputs, whenever the call did NOT succeed (ok == false), then
        // pastBlockTime equals prior value and balance equals prior balance.
        // This captures the general rule: only msg.value == 10 ether can succeed on the reference;
        // the mutant accepting 1 ether will make the call succeed for value == 1 ether and thus
        // violate this assertion for some fuzzed inputs.

        if (!ok) {
            // contract must be unchanged
            assertTrue(c.pastBlockTime() == priorTime && address(c).balance == priorBal);
        } else {
            // If the call succeeded, then msg.value must have been 10 ether in the reference.
            // We do not assert further here because successful calls legitimately change state.
            assertTrue(true);
        }
    }
}

