    // The mutant that requires 1 ether will accept msg.value == 1 ether; thus for some fuzzed inputs (amount == 1 ether)
    // the mutant will succeed while the reference will revert. We express this by asserting the reference ALWAYS reverts
    // whenever amount != 10 ether.
    function testFuzz_property(address caller, uint256 amount) public {
        // Keep domain wide but avoid the zero-address caller which can't be vm.prank'd in some contexts.
        if (caller == address(0)) caller = address(1);

        // bound amount to a reasonably large range to help fuzz explore relevant values
        amount = bound(amount, 0, 20 ether);

        // We are checking behavior for amounts that are not exactly 10 ether.
        vm.assume(amount != 10 ether);

        // Fund the caller so they can send value
        vm.deal(caller, amount);

        bool ok;
        vm.prank(caller);
        // low-level call to trigger fallback payable; using try/catch requires an external call
        // Use (bool success,) = address(c).call{value: amount}(""); but per rules we should wrap in try/catch
        // We instead call via Solidity external call syntax which will compile: call into fallback via address(c).call
        (ok,) = address(c).call{value: amount}("");

        // The reference contract reverts for any amount != 10 ether, so ok must be false for all fuzzed inputs here.
        assertTrue(!ok);
    }
}

