import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: caller address (actor) and two distinct timestamps to drive two fallback calls.
    // We let the fuzzer choose actor and two timestamps; we will ensure timestamps are different and large enough.
    function testFuzz_property(address actor, uint256 t1, uint256 t2) public {
        // admissible constraints: actor must not be zero address (keep wide)
        vm.assume(actor != address(0));
        // bound timestamps into a practical range (avoid very small values like 0 which would make pastBlockTime equal)
        uint256 ts1 = bound(t1, 1, type(uint32).max); // first timestamp
        uint256 ts2 = bound(t2, 1, type(uint32).max); // second timestamp
        // ensure we exercise cases where comparison outcome differs: allow both ordering possibilities
        // we don't restrict ordering to let fuzzer find the crucial case where t2 <= t1 triggers mutant acceptance

        // Fund the actor so they can send 10 ether
        vm.deal(actor, 20 ether);

        // First call: warp to ts1 and have actor call fallback with exactly 10 ether
        vm.warp(ts1);
        vm.prank(actor);
        c.f{value: 10 ether}();

        // Record pastBlockTime after first call (on reference this should be ts1)
        uint256 after1 = c.pastBlockTime();

        // Second call: warp to ts2 and call again with 10 ether
        vm.warp(ts2);
        vm.prank(actor);
        c.f{value: 10 ether}();

        // Single assertion: the reference contract guarantees that after any successful fallback call, pastBlockTime == the timestamp at which that call executed
        // Concretely, after the second call, pastBlockTime should equal the current block.timestamp (ts2) for the reference; the mutant will fail for some inputs (notably when ts2 <= after1)
        assertTrue(c.pastBlockTime() == block.timestamp);
    }
}

