import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameters: actor address and blockNumber that will be used to trigger the conditional transfer
    // We also fuzz a timestamp to set and then reuse to detect whether pastBlockTime was updated.
    function testFuzz_property(address actor, uint256 warpTs, uint256 rollBlock) public {
        // admissible domain: actor must be non-zero, amount must be exactly 10 ether per contract requirement
        vm.assume(actor != address(0));
        // keep timestamp and block in reasonable bounds to avoid vm.warp/roll overflow issues
        warpTs = bound(warpTs, 1, type(uint64).max);
        rollBlock = bound(rollBlock, 1, type(uint64).max);

        // set up actor with funds
        vm.deal(actor, 20 ether);

        // move to chosen block/time
        vm.warp(warpTs);
        vm.roll(uint64(rollBlock));

        // First call: should succeed and update pastBlockTime to current timestamp in the reference
        vm.prank(actor);
        c.f{value: 10 ether}();

        // Read stored pastBlockTime after first call
        uint256 recorded1 = c.pastBlockTime();

        // Now attempt a second call at the same timestamp (no warp change) and same block number
        // For the reference, require(block.timestamp > pastBlockTime) should fail unless pastBlockTime < warpTs.
        // But since reference updated pastBlockTime to warpTs, second call must revert; mutant (not updating) may allow it.
        vm.prank(actor);
        bool ok;
        try c.f{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }

        // After the second attempt, read stored pastBlockTime again
        uint256 recorded2 = c.pastBlockTime();

        // General rule: for the correct contract, after a successful first call at timestamp T,
        // pastBlockTime == T and any immediate second call at the same timestamp must be rejected (so recorded2 == recorded1 and the second call reverts).
        // We assert that recorded2 == recorded1 implies the second call did NOT succeed (ok == false) OR that recorded2 == recorded1
        // (This single assertion distinguishes contracts because the mutant omitting the update can allow ok == true while recorded stays old.)
        // The single assertion must be true for reference for ALL inputs and false for mutant for SOME inputs.

        // We assert: if recorded1 == warpTs then the second call must have reverted (ok == false).
        // This encodes the universal property: after recording the timestamp, an immediate same-timestamp call is rejected.
        assertTrue(!(recorded1 == warpTs) || (ok == false));
    }
}

