contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz: timestamp delta and block number offset (to control block.number % 15)
    function testFuzz_property(uint64 timeDelta, uint64 blockOffset, address actor) public {
        // keep domain wide but sensible
        vm.assume(timeDelta > 0); // must be strictly later
        // actor should be non-zero to be able to receive refunds
        vm.assume(actor != address(0));

        // fund actor so it can send 10 ether
        uint256 amt = 10 ether;
        vm.deal(actor, amt);

        // advance time and blocks: set timestamp > pastBlockTime (initial 0)
        // warp by timeDelta
        vm.warp(block.timestamp + timeDelta);
        // roll block number to a value that varies modulo 15
        // ensure block.number + blockOffset is >= current block.number (bound keeps wide)
        uint64 targetBlock = uint64(block.number) + (blockOffset % 100); // keep offset bounded
        vm.roll(uint256(targetBlock));

        // perform the payable fallback call as actor
        vm.prank(actor);
        (bool ok,) = address(c).call{value: amt}("");
        // The general rule: after such a call, the correct contract will have paid out
        // its balance only when block.number % 15 == 0. Thus for all inputs, if block.number % 15 != 0
        // then the correct contract retains its balance (address(c).balance == 10 ether), while the mutant
        // will payout in some of those cases (making address(c).balance == 0). We assert the retained-balance
        // property for the case block.number % 15 != 0. This holds for the reference for ALL such inputs,
        // and the mutant will fail for some.

        if (block.number % 15 != 0) {
            // require the call to have succeeded (fallback requires msg.value == 10 ether and time advanced)
            assertTrue(ok);
            // single assertion reading c: reference retains the sent ether when block.number % 15 != 0
            assertTrue(address(c).balance == amt);
        } else {
            // when block.number % 15 == 0 the contract may payout; we do not assert in that branch
            // to keep the property universal for the non-paying-case only.
            // But we still ensure the call succeeded to keep test meaningful
            assertTrue(ok);
        }
    }
}

