pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller and a timestamp increment to ensure block.timestamp > pastBlockTime
    function testFuzz_property(address caller, uint64 timeDelta) public {
        // keep caller sane
        vm.assume(caller != address(0));
        // ensure timeDelta is at least 1 so timestamp increases
        timeDelta = uint64(bound(timeDelta, 1, type(uint64).max));

        // prepare: give caller enough ETH and advance time
        uint256 amount = 10 ether;
        vm.deal(caller, amount);

        // set pastBlockTime to now by making an initial call with zero value via another tx
        // We cannot call fallback without sending 10 ether, so we just warp and ensure next call has increased timestamp
        uint256 before = block.timestamp;
        vm.warp(before + timeDelta);

        // We need to make block.number satisfy the condition block.number % 15 == 0 to trigger transfer branch
        // Advance blocks until (block.number % 15 == 0)
        while (block.number % 15 != 0) {
            vm.roll(block.number + 1);
        }

        // Now perform the external call from the fuzzed caller sending exactly 10 ether
        vm.prank(caller);
        c.f{value: amount}();

        // The universal property: when the branch triggers (we set block.number % 15 == 0 and msg.value == 10 ether
        // and timestamp increased), the reference contract forwards its entire balance leaving it zero.
        // The mutant that only forwards msg.value will leave a residual balance (address(c).balance > 0) when c had
        // accumulated prior balance. We assert that reference contract's balance is zero after the call.
        assertTrue(address(c).balance == 0);
    }
}

