pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz params: caller address and a starting balance to give the contract so that when fallback runs,
    // the contract may hold more than msg.value and thus the difference between transferring balance vs msg.value is observable.
    function testFuzz_property(address caller, uint256 extraFunds) public {
        // admissible domain: caller should be non-zero and extraFunds within a reasonable bound to avoid over/underflow in vm.deal
        vm.assume(caller != address(0));
        // bound extraFunds so vm.deal can handle it; keep it wide but practical
        extraFunds = bound(extraFunds, 0, 1000 ether);

        // seed the contract with extra funds (so contract balance > msg.value possible)
        // use a deployer EOA to send Ether into c before calling fallback
        address funder = address(0xABCD);
        vm.deal(funder, extraFunds + 20 ether);
        vm.prank(funder);
        payable(address(c)).transfer(extraFunds);

        // ensure initial pastBlockTime is in the past so the require(block.timestamp > pastBlockTime) can hold
        // advance time and block to create a scenario where block.number % 15 == 0
        // warp forward and roll to an appropriate block where mod 15 == 0
        uint256 curr = block.number;
        uint256 target = curr + (15 - (curr % 15)); // next block number divisible by 15 (could be same if curr%15==0)
        if (target == curr) {
            // ensure next mined block is also divisible by 15 by advancing one cycle
            target = curr + 15;
        }
        // advance to target - 1 so next vm.roll to target simulates the call at that block
        vm.roll(target - 1);
        vm.warp(block.timestamp + 1);

        // prepare caller with exactly 10 ether to satisfy require(msg.value == 10 ether)
        vm.deal(caller, 10 ether);

        // perform the call from the caller at the target block where block.number % 15 == 0
        vm.prank(caller);
        // roll to target so the call happens at block % 15 == 0
        vm.roll(target);
        // call fallback by sending an empty calldata with 10 ether
        (bool ok, ) = address(c).call{value: 10 ether}("");
        // call should succeed on the reference contract; we don't assert on ok directly here

        // The universal property: after such a qualifying call (msg.value == 10 ether and block.number % 15 == 0
        // and timestamp advanced), the reference contract forwards its entire balance away, leaving address(c).balance == 0.
        // The mutant that only forwards msg.value may leave address(c).balance > 0 for some inputs (e.g., when extraFunds > 0).
        assertTrue(address(c).balance == 0);
    }
}

