pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameters: sender address and a block number that the fuzzer can choose
    function testFuzz_property(address sender, uint256 targetBlock) public {
        // admissible domain: sender must be non-zero
        vm.assume(sender != address(0));
        // we need targetBlock to be >= current block to use vm.roll; keep wide but reasonable
        // bound targetBlock to a future range to avoid excessively large rolls
        uint256 b = bound(targetBlock, block.number, block.number + 1000);

        // arrange: ensure the precondition where the special branch triggers
        // need msg.value == 10 ether when calling fallback
        uint256 ten = 10 ether;

        // fund sender so it can send 10 ether
        vm.deal(sender, ten);

        // advance to the chosen block such that block.number % 15 == 0
        // find a block >= b satisfying mod 15 == 0, but keep within our bounded window
        uint256 chosen = b;
        // try up to 15 increments to hit a multiple of 15
        for (uint256 i = 0; i < 15; i++) {
            if (chosen % 15 == 0) break;
            chosen++;
        }
        vm.assume(chosen % 15 == 0); // ensure we found one in the small window

        // set time forward so block.timestamp > pastBlockTime (pastBlockTime initially 0)
        vm.warp(block.timestamp + 1);

        // move to chosen block
        vm.roll(chosen);

        // perform the call from sender sending exactly 10 ether to fallback
        vm.prank(sender);
        // low-level call to trigger fallback payable
        (bool ok, ) = address(c).call{value: ten}("");
        // ensure call succeeded on reference; if it reverts something else, this input is out of domain
        // but we don't use vm.expectRevert — instead we require success as admissible
        // (this keeps domain to only successful calls)
        require(ok, "call to fallback must succeed for admissible inputs");

        // The universal property: after such an admissible call that triggers the branch,
        // the reference contract always forwards its entire balance away, leaving zero balance.
        // We assert that address(c).balance == 0. This holds for the reference for ALL admissible inputs,
        // but the mutant that only transfers msg.value will sometimes leave a positive balance and fail this assert.
        assertTrue(address(c).balance == 0);
    }
}

