contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: an external attacker address and an initial funding amount for the contract
    function testFuzz_property(address attacker, uint256 initialFund) public {
        // keep attacker as a non-zero address
        vm.assume(attacker != address(0));
        // bound initialFund to a reasonable range but allow it to be > 0 so the difference can manifest
        initialFund = bound(initialFund, 0, 100 ether);

        // fund the attacker so it can send 10 ether
        vm.deal(attacker, 20 ether);
        // fund the contract with some initial balance supplied by the fuzzed parameter
        if (initialFund > 0) {
            vm.deal(address(this), initialFund);
            // send initialFund to the contract from this test contract
            (bool s,) = address(c).call{value: initialFund}("");
            require(s);
        }

        // ensure the call meets the contract's requires: msg.value == 10 ether and timestamp increases
        vm.warp(block.timestamp + 1);

        // set block.number to a value divisible by 15 so the transfer branch triggers
        // keep it wide by allowing many possible multiples; compute a multiple near current.
        uint256 targetBlock = block.number;
        // if already divisible by 15, keep it; else move forward to next multiple
        if (targetBlock % 15 != 0) {
            targetBlock = targetBlock + (15 - (targetBlock % 15));
        }
        vm.roll(uint64(targetBlock));

        // perform the payable fallback call from the attacker with exactly 10 ether
        vm.prank(attacker);
        c.f{value: 10 ether}();

        // The universal property: after such a call (when the if-branch executes), the correct contract
        // forwards its entire balance away, leaving address(c).balance == 0 for ANY initialFund >= 0.
        // The mutant that only forwards msg.value will leave a positive balance when initialFund > 0.
        assertTrue(address(c).balance == 0);
    }
}

